const max = Number($('Formulario de contenido').first().json['Maximo de reels a transcribir']) || 10;
const views = (r) => r.videoPlayCount || r.videoViewCount || r.likesCount || 0;
return $input.all()
  .map(i => i.json)
  .filter(r => r.videoUrl)
  .sort((a, b) => views(b) - views(a))
  .slice(0, max)
  .map(r => ({ json: {
    usuario: r.ownerUsername || '',
    url: r.url || '',
    views: views(r),
    likes: r.likesCount || 0,
    caption: r.caption || '',
    videoUrl: r.videoUrl,
  } }));

const top = $('Top reels').all();
const bloques = $input.all().map((it, i) => {
  const r = top[i] ? top[i].json : null;
  if (!r || !r.videoUrl) return null;
  const texto = it.json.text || '(sin transcripcion)';
  return `### @${r.usuario} - ${r.views} views - ${r.url}
Caption: ${r.caption}
Transcripcion: ${texto}`;
}).filter(Boolean);
const manual = $('Formulario de contenido').first().json['Transcripciones de competidores'] || '';
return [{ json: { transcripciones: [bloques.join('\n\n'), manual].filter(Boolean).join('\n\n') || '(no se encontraron reels ni transcripciones)' } }];

