  `# Plan de contenido - ${marca}`,
  `# 1. Ideas (analisis de competencia)`, t('Agente 1 - Generador de ideas'),
  `# 2. Copywriting: hooks, guiones, descripciones y CTAs`, t('Agente 2 - Copywriter'),
  `# 3. Trial Reels`, t('Agente 3 - Generador de Trial Reels'),
  `# 4. Planificacion semanal`, t('Agente 4 - Planificador de contenido'),
  `# 5. Lead magnet`, t('Agente 5 - Disenador de lead magnets'),
].join('\n\n---\n\n');
return [{ json: { markdown: md } }];
